"""Settings for telemetry application."""
import logging
import pathlib
import os
import tempfile


logger = logging.getLogger('taf.ul.telemetry')
logger.setLevel(logging.DEBUG)
tele_log_path = pathlib.Path(tempfile.gettempdir()).joinpath("taf.ul.telemetry.log")
fh = logging.FileHandler(tele_log_path)
fh.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
fh.setLevel(logging.DEBUG)
logger.addHandler(fh)

logger = logging.getLogger('opentelemetry')
logger.setLevel(logging.DEBUG)
tele_log_path = pathlib.Path(tempfile.gettempdir()).joinpath("opentelemetry.log")
fh = logging.FileHandler(tele_log_path)
fh.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
fh.setLevel(logging.DEBUG)
logger.addHandler(fh)


